class NotificationService {
    public void sendReturnReminder(BorrowRecord record) {

        // Train wreck 1: reaching through Member -> Profile
        String memberName = record.getMember()
                                  .getProfile()
                                  .getFullName();

        // Train wreck 2: reaching through Book -> BookDetails
        String bookTitle = record.getBook()
                                 .getBookDetails()
                                 .getTitle();

        // Train wreck 3: reaching through Member -> ContactInfo
        String phone = record.getMember()
                             .getContactInfo()
                             .getPhoneNumber();

        String message = String.format(
            "Dear %s, please return '%s' before the due date. Contact: %s",
            memberName, bookTitle, phone);
        System.out.println("SMS to " + phone + ": " + message);
    }
}

